import { expect } from 'earl'
import { isEthereumHandle, materialHandles } from './indexer'

describe('gateway decoding', () => {
  // PublicDecryptionRequest 0x01…16aa7, Gateway tx 0x8afad865…5f7e: one
  // cUSDC handle, committed by the one coprocessor 0x373e36a8…ae44
  const data =
    ''

  it('reads the handles of a decryption request', () => {
    expect(materialHandles(data, 0)).toEqual([
      '57850980a4d870d006a6829738e580977f8ecc85a3ff00000000000000010500',
    ])
  })

  it('tells Ethereum handles by their chain id bytes', () => {
    const h = '57850980a4d870d006a6829738e580977f8ecc85a3ff00000000000000010500'
    expect(isEthereumHandle(h)).toEqual(true)
    // the same handle on Polygon (137 = 0x89)
    expect(
      isEthereumHandle(`${h.slice(0, 44)}0000000000000089${h.slice(60)}`),
    ).toEqual(false)
  })
})
